	"time"
)

// PollStatusUpdater persists poll status for a source.
type PollStatusUpdater interface {
	UpdateSourcePollStatus(ctx context.Context, id string, pollErr error) error
}

// Orchestrator runs polling ingestion sources on a fixed interval.
type Orchestrator struct {
	service       *Service
	loader        *SourceLoader
	pollUpdater   PollStatusUpdater
	staticSources []IIngestionSource // for testing only
	interval      time.Duration
}

// NewOrchestrator creates an orchestrator that dynamically loads enabled
// sources from the database on each poll cycle.
func NewOrchestrator(service *Service, loader *SourceLoader, pollUpdater PollStatusUpdater, interval time.Duration) *Orchestrator {
	return &Orchestrator{service: service, loader: loader, pollUpdater: pollUpdater, interval: interval}
}

// NewOrchestratorWithSources creates an orchestrator with a static source list.
// Intended for testing; production code should use NewOrchestrator with a SourceLoader.
func NewOrchestratorWithSources(service *Service, sources []IIngestionSource, interval time.Duration) *Orchestrator {
	return &Orchestrator{service: service, staticSources: sources, interval: interval}
}

// Run polls all sources immediately, then on every tick. Blocks until ctx is cancelled.
func (o *Orchestrator) Run(ctx context.Context) {
	ticker := time.NewTicker(o.interval)
	defer ticker.Stop()

	o.pollAll(ctx)

	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			o.pollAll(ctx)
		}
	}
}

func (o *Orchestrator) pollAll(ctx context.Context) {
	sources := o.staticSources
	if sources == nil {
		scheduled, err := o.loader.LoadEnabledSources(ctx)
		if err != nil {
			slog.Error("load sources failed", "err", err)
			return
		}
		if len(scheduled) == 0 {
			slog.Debug("no enabled sources to poll")
			return
		}
		now := time.Now()
		for _, ss := range scheduled {
			if ss.LastPolledAt != nil {
				interval := time.Duration(ss.PollIntervalSeconds) * time.Second
				if now.Before(ss.LastPolledAt.Add(interval)) {
					continue
				}
			}
			o.pollSource(ctx, ss.Source)
		}
		return
	}
	if len(sources) == 0 {
		slog.Debug("no enabled sources to poll")
		return
	}
	for _, src := range sources {
		o.pollSource(ctx, src)
	}
}

func (o *Orchestrator) pollSource(ctx context.Context, src IIngestionSource) {
	results, err := src.FetchNewReleases(ctx)
	if err != nil {
		slog.Error("poll failed", "source", src.Name(), "err", err)
		o.updateSourcePollStatus(ctx, src.SourceID(), err)
		return
	}
	o.updateSourcePollStatus(ctx, src.SourceID(), nil)
	if len(results) == 0 {
		return
	}
	if err := o.service.ProcessResults(ctx, src.SourceID(), src.Name(), results); err != nil {
		slog.Error("process failed", "source", src.Name(), "err", err)
	}
}

func (o *Orchestrator) updateSourcePollStatus(ctx context.Context, sourceID string, pollErr error) {
	if o.pollUpdater == nil {
		return
	}
	if err := o.pollUpdater.UpdateSourcePollStatus(ctx, sourceID, pollErr); err != nil {
		slog.Error("update source poll status", "source", sourceID, "err", err)
	}
}

package ingestion

import (
	"context"
	"fmt"
	"log/slog"
	"net/http"
	"time"

	"github.com/sentioxyz/changelogue/internal/githubauth"
)

// SourceLister abstracts the database query for enabled sources so both
// PostgreSQL and SQLite stores can provide sources to the orchestrator.
type SourceLister interface {
	ListEnabledSources(ctx context.Context) ([]EnabledSource, error)
}

// EnabledSource carries the fields the loader needs to construct an IIngestionSource.
type EnabledSource struct {
	ID                  string
	Provider            string
	Repository          string
	PollIntervalSeconds int
	LastPolledAt        *time.Time
}

// ScheduledSource wraps an IIngestionSource with its scheduling metadata
// so the orchestrator can decide whether the source is due for polling.
type ScheduledSource struct {
	Source              IIngestionSource
	PollIntervalSeconds int
	LastPolledAt        *time.Time
}

// SourceLoader reads source configuration from the database and constructs
// IIngestionSource instances. It bridges the API-managed sources table with
// the polling orchestrator.
type SourceLoader struct {
	lister        SourceLister
	client        *http.Client
	tokenProvider githubauth.TokenProvider
}

func NewSourceLoader(lister SourceLister, client *http.Client) *SourceLoader {
	return NewSourceLoaderWithTokenProvider(lister, client, githubauth.NewDefaultTokenProvider(client, ""))
}

func NewSourceLoaderWithTokenProvider(lister SourceLister, client *http.Client, tokenProvider githubauth.TokenProvider) *SourceLoader {
	return &SourceLoader{lister: lister, client: client, tokenProvider: tokenProvider}
}

// LoadEnabledSources queries all enabled sources and constructs the
// appropriate IIngestionSource for each one, along with scheduling metadata.
func (l *SourceLoader) LoadEnabledSources(ctx context.Context) ([]ScheduledSource, error) {
	enabled, err := l.lister.ListEnabledSources(ctx)
	if err != nil {
		return nil, fmt.Errorf("list enabled sources: %w", err)
	}
	var sources []ScheduledSource
	for _, e := range enabled {
		src := BuildSourceWithTokenProvider(l.client, e.ID, e.Provider, e.Repository, l.tokenProvider)
		if src == nil {
			slog.Warn("unsupported source type, skipping",
				"id", e.ID, "type", e.Provider, "repo", e.Repository)
			continue
		}
		sources = append(sources, ScheduledSource{
			Source:              src,
			PollIntervalSeconds: e.PollIntervalSeconds,
			LastPolledAt:        e.LastPolledAt,
		})
	}
	return sources, nil
}

// BuildSource constructs the appropriate IIngestionSource based on provider type.
func BuildSource(client *http.Client, id string, sourceType, repository string) IIngestionSource {
	return BuildSourceWithTokenProvider(client, id, sourceType, repository, githubauth.NewDefaultTokenProvider(client, ""))
}

func BuildSourceWithTokenProvider(client *http.Client, id string, sourceType, repository string, tokenProvider githubauth.TokenProvider) IIngestionSource {
	switch sourceType {
	case "dockerhub":
		return NewDockerHubSource(client, repository, id)
	case "github":
		return NewGitHubSourceWithTokenProvider(client, repository, id, tokenProvider)
	case "ecr-public":
		return NewECRPublicSource(client, repository, id)
	case "ghcr":
		return NewGHCRSource(client, repository, id)
	case "gitlab":
		return NewGitLabSource(client, repository, id)
	case "pypi":
		return NewPyPISource(client, repository, id)
	case "npm":
		return NewNpmSource(client, repository, id)
	default:
		return nil
	}
}

