	ListAllSourceRepos(ctx context.Context) ([]models.SourceRepo, error)
}

// SourcesHandler implements HTTP handlers for the /sources resource.
type SourcesHandler struct {
	store            SourcesStore
	ingestionService *ingestion.Service
	httpClient       *http.Client
	tokenProvider    githubauth.TokenProvider
}

// NewSourcesHandler returns a new SourcesHandler.
func NewSourcesHandler(store SourcesStore, ingestionService *ingestion.Service, httpClient *http.Client, tokenProvider githubauth.TokenProvider) *SourcesHandler {
	if tokenProvider == nil {
		tokenProvider = githubauth.NewDefaultTokenProvider(httpClient, "")
	}
	return &SourcesHandler{store: store, ingestionService: ingestionService, httpClient: httpClient, tokenProvider: tokenProvider}
}

// List handles GET /projects/{projectId}/sources — returns a paginated list of sources for a project.
func (h *SourcesHandler) List(w http.ResponseWriter, r *http.Request) {
	projectID := r.PathValue("projectId")
	if projectID == "" {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Project ID is required")
		return
	}
	page, perPage := ParsePagination(r)
	sources, total, err := h.store.ListSourcesByProject(r.Context(), projectID, page, perPage)
	if err != nil {
		RespondError(w, r, http.StatusInternalServerError, "internal_error", "Failed to list sources")
		return
	}
	if sources == nil {
		sources = []models.Source{}
	}
	RespondList(w, r, http.StatusOK, sources, page, perPage, total)
}

// ListAll handles GET /sources — returns a paginated list of all sources.
func (h *SourcesHandler) ListAll(w http.ResponseWriter, r *http.Request) {
	page, perPage := ParsePagination(r)
	sources, total, err := h.store.ListAllSources(r.Context(), page, perPage)
	if err != nil {
		RespondError(w, r, http.StatusInternalServerError, "internal_error", "Failed to list sources")
		return
	}
	if sources == nil {
		sources = []models.Source{}
	}
	RespondList(w, r, http.StatusOK, sources, page, perPage, total)
}

// Create handles POST /projects/{projectId}/sources — creates a new source under a project.
func (h *SourcesHandler) Create(w http.ResponseWriter, r *http.Request) {
	projectID := r.PathValue("projectId")
	if projectID == "" {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Project ID is required")
		return
	}
	var src models.Source
	body, err := io.ReadAll(r.Body)
	if err != nil {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid request body")
		return
	}
	if err := json.Unmarshal(body, &src); err != nil {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid JSON body")
		return
	}
	applySourceDefaults(body, &src)
	src.ProjectID = projectID
	src.Provider = strings.TrimSpace(src.Provider)
	src.Repository = strings.TrimSpace(src.Repository)
	if src.Provider == "" {
		RespondError(w, r, http.StatusUnprocessableEntity, "validation_error", "provider is required")
		return
	}
	if src.Repository == "" {
		RespondError(w, r, http.StatusUnprocessableEntity, "validation_error", "repository is required")
		return
	}
	if err := h.store.CreateSource(r.Context(), &src); err != nil {
		RespondError(w, r, http.StatusInternalServerError, "internal_error", "Failed to create source")
		return
	}
	go h.pollSourceAsync(src.ID, src.Provider, src.Repository, src.ReleasesOnly)
	RespondJSON(w, r, http.StatusCreated, src)
}

// applySourceDefaults sets defaults for fields omitted from the create request.
// New sources exclude prereleases and watch releases only unless told otherwise.
func applySourceDefaults(body []byte, src *models.Source) {
	var present struct {
		ExcludePrereleases *bool `json:"exclude_prereleases"`
		ReleasesOnly       *bool `json:"releases_only"`
	}
	_ = json.Unmarshal(body, &present)
	if present.ExcludePrereleases == nil {
		src.ExcludePrereleases = true
	}
	if present.ReleasesOnly == nil {
		src.ReleasesOnly = true
	}
}

// Get handles GET /sources/{id} — returns a single source.
func (h *SourcesHandler) Get(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid source ID")
		return
	}
	src, err := h.store.GetSource(r.Context(), id)
	if err != nil {
		RespondError(w, r, http.StatusNotFound, "not_found", "Source not found")
		return
	}
	RespondJSON(w, r, http.StatusOK, src)
}

// Update handles PUT /sources/{id} — updates an existing source.
func (h *SourcesHandler) Update(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid source ID")
		return
	}
	var src models.Source
	if err := DecodeJSON(r, &src); err != nil {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid JSON body")
		return
	}
	src.Provider = strings.TrimSpace(src.Provider)
	src.Repository = strings.TrimSpace(src.Repository)
	if src.Provider == "" {
		RespondError(w, r, http.StatusUnprocessableEntity, "validation_error", "provider is required")
		return
	}
	if src.Repository == "" {
		RespondError(w, r, http.StatusUnprocessableEntity, "validation_error", "repository is required")
		return
	}
	if err := h.store.UpdateSource(r.Context(), id, &src); err != nil {
		RespondError(w, r, http.StatusNotFound, "not_found", "Source not found")
		return
	}
	src.ID = id
	go h.pollSourceAsync(id, src.Provider, src.Repository, src.ReleasesOnly)
	RespondJSON(w, r, http.StatusOK, src)
}

// Delete handles DELETE /sources/{id} — deletes a source.
func (h *SourcesHandler) Delete(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid source ID")
		return
	}
	if err := h.store.DeleteSource(r.Context(), id); err != nil {
		RespondError(w, r, http.StatusNotFound, "not_found", "Source not found")
		return
	}
	w.WriteHeader(http.StatusNoContent)
}

// FetchReleases handles POST /sources/{id}/poll — polls upstream for new
// releases, ingests them, and updates last_polled_at.
func (h *SourcesHandler) FetchReleases(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("id")
	if id == "" {
		RespondError(w, r, http.StatusBadRequest, "bad_request", "Invalid source ID")
		return
	}
	src, err := h.store.GetSource(r.Context(), id)
	if err != nil {
		RespondError(w, r, http.StatusNotFound, "not_found", "Source not found")
		return
	}

	ingestionSrc := ingestion.BuildSourceWithTokenProvider(h.httpClient, src.ID, src.Provider, src.Repository, h.tokenProvider, ingestion.SourceOptions{ReleasesOnly: src.ReleasesOnly})
	if ingestionSrc == nil {
		RespondError(w, r, http.StatusUnprocessableEntity, "unsupported_provider", "Unsupported provider: "+src.Provider)
		return
	}

	results, err := ingestionSrc.FetchNewReleases(r.Context())
	if err != nil {
		slog.Error("fetch releases failed", "source", src.ID, "err", err)
		_ = h.store.UpdateSourcePollStatus(r.Context(), src.ID, err)
		RespondError(w, r, http.StatusBadGateway, "upstream_error", "Failed to fetch releases from upstream")
		return
	}

	_ = h.store.UpdateSourcePollStatus(r.Context(), src.ID, nil)

	newCount := 0
	if len(results) > 0 && h.ingestionService != nil {
		for _, result := range results {
			if procErr := h.ingestionService.ProcessResults(r.Context(), src.ID, src.Provider, []ingestion.IngestionResult{result}); procErr != nil {
				slog.Error("process release failed", "source", src.ID, "version", result.RawVersion, "err", procErr)
				continue
			}
			newCount++
		}
	}

	RespondJSON(w, r, http.StatusOK, map[string]int{"new_releases": newCount})
}

// pollSourceAsync polls a source in the background and updates its poll status.
func (h *SourcesHandler) pollSourceAsync(sourceID, provider, repository string, releasesOnly bool) {
	ctx := context.Background()

	ingestionSrc := ingestion.BuildSourceWithTokenProvider(h.httpClient, sourceID, provider, repository, h.tokenProvider, ingestion.SourceOptions{ReleasesOnly: releasesOnly})
	if ingestionSrc == nil {
		slog.Warn("async poll: unsupported provider", "source", sourceID, "provider", provider)
		return
	}

	slog.Info("async poll triggered", "source", sourceID, "provider", provider, "repository", repository)

	results, err := ingestionSrc.FetchNewReleases(ctx)
	if err != nil {
		slog.Error("async poll failed", "source", sourceID, "err", err)
		_ = h.store.UpdateSourcePollStatus(ctx, sourceID, err)
		return
	}

	_ = h.store.UpdateSourcePollStatus(ctx, sourceID, nil)

	if len(results) > 0 && h.ingestionService != nil {
		for _, result := range results {
			if procErr := h.ingestionService.ProcessResults(ctx, sourceID, provider, []ingestion.IngestionResult{result}); procErr != nil {
				slog.Error("async poll: process release failed", "source", sourceID, "version", result.RawVersion, "err", procErr)
			}
		}
	}
}

